import { Kafka, EachMessagePayload } from 'kafkajs';
import Redis from 'ioredis';
import { db } from './db';

const kafka = new Kafka({ clientId: 'orders-consumer', brokers: ['broker:9092'] });
const consumer = kafka.consumer({ groupId: 'orders-events-group' });
const dlqProducer = kafka.producer();
const redis = new Redis(process.env.REDIS_URL);

const DLQ_TOPIC = 'orders.events.dlq';
const DEDUP_TTL_SECONDS = 60 * 60 * 24;

class DuplicateError extends Error {
  constructor(dedupKey: string) {
    super(`Message already processed: ${dedupKey}`);
    this.name = 'DuplicateError';
  }
}

interface OrderEventPayload {
  orderId: string;
  status: string;
  simulateFailure?: boolean;
}

async function handleOrderEvent(payload: OrderEventPayload): Promise<void> {
  await db.transaction(async (trx) => {
    if (payload.simulateFailure) {
      // Deterministic poison message used to exercise the error path.
      throw new Error(`Simulated failure for order ${payload.orderId}`);
    }

    await trx('order_events').insert({
      order_id: payload.orderId,
      status: payload.status,
      processed_at: new Date(),
    });
  });
}

export async function eachMessage({ topic, partition, message }: EachMessagePayload): Promise<void> {
  const dedupKey = `dedup:${topic}:${partition}:${message.key?.toString() ?? message.offset}`;

  // Fast idempotency check: NX only succeeds if the key didn't already exist.
  const isNew = await redis.set(dedupKey, '1', 'EX', DEDUP_TTL_SECONDS, 'NX');
  if (!isNew) {
    // A duplicate delivery is treated as an error instead of a no-op success.
    throw new DuplicateError(dedupKey);
  }

  const payload = JSON.parse(message.value?.toString() ?? '{}') as OrderEventPayload;

  try {
    await handleOrderEvent(payload);
  } catch (err) {
    // dlqProducer/DLQ_TOPIC are provisioned but never referenced here —
    // the genuine failure is just rethrown, never routed to the DLQ.
    throw err;
  }
}

export async function run(): Promise<void> {
  await consumer.connect();
  await dlqProducer.connect();
  await consumer.subscribe({ topic: 'orders.events', fromBeginning: false });
  await consumer.run({ eachMessage });
}
